 Future<void> add()async{final n=TextEditingController(),p=TextEditingController(),e=TextEditingController(),s=TextEditingController();final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('إضافة مدرس'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:n,decoration:const InputDecoration(labelText:'الاسم'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:p,decoration:const InputDecoration(labelText:'الهاتف')),TextFormField(controller:e,decoration:const InputDecoration(labelText:'البريد')),TextFormField(controller:s,decoration:const InputDecoration(labelText:'التخصص'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(c,true);},child:const Text('حفظ'))]));if(ok==true){try{await ApiService.post('teachers',{'name':n.text.trim(),'phone':p.text.trim(),'email':e.text.trim(),'specialization':s.text.trim(),'status':'active'});await load();}catch(x){msg(x);}}for(final c in[n,p,e,s])c.dispose();}
 Future<void> details(int id)async{try{final r=await ApiService.get('teachers/$id');final d=Map<String,dynamic>.from(r is Map&&r['data'] is Map?r['data']:r);if(!mounted)return;final studentsList=list(d['students']);final assignments=list(d['assignments']);final privateLessons=list(d['private_lessons']);final groupLessons=list(d['group_lessons']);await showDialog(context:context,builder:(c)=>AlertDialog(title:Text('${d['teacher']?['name']??'المدرس'}'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الطلاب المرتبطون: ${studentsList.length}',style:const TextStyle(fontWeight:FontWeight.bold)),...studentsList.map((x)=>Text('• ${x['name']??''}')),const Divider(),Text('أسعار الحصص',style:const TextStyle(fontWeight:FontWeight.bold)),...assignments.map((x){final rate=double.tryParse('${x['teacher_rate']??0}')??0;final pct=double.tryParse('${x['academy_percentage']??0}')??0;final total=rate*(1+pct/100);return Text('• ${x['student']?['name']??''} / ${x['subject']??''} — ${rate.toStringAsFixed(2)} + ${pct.toStringAsFixed(2)}% = ${total.toStringAsFixed(2)}');}),const Divider(),Text('Private: ${privateLessons.length}'),Text('Group: ${groupLessons.length}'),Text('المستحق: ${d['due']??0}'),Text('المدفوع: ${d['paid']??0}'),Text('المتبقي: ${d['remaining']??0}',style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),FilledButton.icon(onPressed:(){Navigator.pop(c);assignmentDialog(id);},icon:const Icon(Icons.link),label:const Text('ربط طالب ومادة وسعر'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
 Future<void> assignmentDialog(int teacherId)async{if(students.isEmpty||subjects.isEmpty){msg(Exception('أضف طالبًا ومواد أولًا'));return;}int studentId=students.first['id'];String subject='${subjects.first}';int? supervisorId;final rate=TextEditingController();final pct=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD){final total=(double.tryParse(rate.text)??0)*(1+(double.tryParse(pct.text)??0)/100);return AlertDialog(title:const Text('علاقة المدرس بالطالب'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:studentId,decoration:const InputDecoration(labelText:'الطالب'),items:students.map((x)=>DropdownMenuItem<int>(value:x['id'] as int,child:Text('${x['name']}'))).toList(),onChanged:(v){if(v!=null)setD(()=>studentId=v);}),DropdownButtonFormField<String>(value:subject,decoration:const InputDecoration(labelText:'المادة'),items:subjects.map((x)=>DropdownMenuItem<String>(value:'$x',child:Text('$x'))).toList(),onChanged:(v){if(v!=null)setD(()=>subject=v);}),TextField(controller:rate,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سعر الحصة للمدرس'),onChanged:(_)=>setD((){})),TextField(controller:pct,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'نسبة الأكاديمية %'),onChanged:(_)=>setD((){})),if(supervisors.isNotEmpty)DropdownButtonFormField<int?>(value:supervisorId,decoration:const InputDecoration(labelText:'المشرف اختياري'),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون مشرف')),...supervisors.map((x)=>DropdownMenuItem<int?>(value:x['id'] as int,child:Text('${x['name']}')))],onChanged:(v)=>setD(()=>supervisorId=v)),const SizedBox(height:8),Text('الإجمالي النهائي: ${total.toStringAsFixed(2)}',style:const TextStyle(fontWeight:FontWeight.bold))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حفظ'))]));if(ok==true){try{await ApiService.post('teacher-assignments',{'teacher_id':teacherId,'student_id':studentId,'subject':subject,'teacher_rate':double.tryParse(rate.text)??0,'academy_percentage':double.tryParse(pct.text)??0,'supervisor_id':supervisorId});await load();}catch(e){msg(e);}}rate.dispose();pct.dispose();}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('المدرسون'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:add,backgroundColor:AppColors.red,child:const Icon(Icons.add)),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:teachers.length,itemBuilder:(_,i){final t=teachers[i];return Card(child:ListTile(onTap:()=>details(t['id']),title:Text('${t['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${t['phone']??t['email']??''}'),trailing:const Icon(Icons.chevron_left)));})));}
}
